{"explanation":"The chance is about **8.3%**, assuming “90% accurate” means 90% sensitivity and 90% specificity. Among 1,000 people, about 9 sick people test positive—but so do 99 healthy people. So only 9 of the 108 positive results indicate disease: 9 ÷ 108 ≈ 8.3%.","manimCode":"const title = new Text({ text: 'A positive test is not a diagnosis', fontSize: 32, color: WHITE });
title.moveTo([0, 3.2, 0]);
const population = new Text({ text: 'Imagine 1,000 people', fontSize: 25, color: WHITE });
population.moveTo([0, 2.35, 0]);

const sickBox = new Rectangle({ width: 4.7, height: 1.65, color: BLUE });
sickBox.moveTo([-2.9, 0.95, 0]);
sickBox.setFill(BLUE, 0.12);
const healthyBox = new Rectangle({ width: 4.7, height: 1.65, color: ORANGE });
healthyBox.moveTo([2.9, 0.95, 0]);
healthyBox.setFill(ORANGE, 0.12);
const sickArrow = new Arrow({ start: [-0.8, 2.05, 0], end: [-2.9, 1.86, 0], color: BLUE });
const healthyArrow = new Arrow({ start: [0.8, 2.05, 0], end: [2.9, 1.86, 0], color: ORANGE });

await scene.play(new Write(title));
await scene.play(new AnimationGroup([new FadeIn(population), new Create(sickBox), new Create(healthyBox), new Create(sickArrow), new Create(healthyArrow)]));

const trueSegment = new Polygon({ vertices: [[-5.3,-1.55,0],[-4.5,-1.55,0],[-4.5,-0.95,0],[-5.3,-0.95,0]], color: BLUE });
trueSegment.setFill(BLUE, 0.85);
const falseSegment = new Polygon({ vertices: [[-4.5,-1.55,0],[5.3,-1.55,0],[5.3,-0.95,0],[-4.5,-0.95,0]], color: ORANGE });
falseSegment.setFill(ORANGE, 0.85);
scene.add(trueSegment, falseSegment);

const legendTrue = new Text({ text: 'Sick + positive', fontSize: 21, color: BLUE });
legendTrue.moveTo([-3.15, -1.9, 0]);
const legendFalse = new Text({ text: 'Healthy + positive', fontSize: 21, color: ORANGE });
legendFalse.moveTo([2.7, -1.9, 0]);
scene.add(legendTrue, legendFalse);

const formula = new MathTex({ latex: 'P(\\mathrm{sick}\\mid +)=\\frac{\\mathrm{true\\ positives}}{\\mathrm{all\\ positives}}' });
await formula.waitForRender();
formula.scale(0.7);
formula.moveTo([-1.3, -3.12, 0]);
scene.add(formula);

let prevalence = 1;
let dynamicLabels = [];
function fmt(value) {
  return Math.abs(value - Math.round(value)) < 0.000001 ? String(Math.round(value)) : value.toFixed(1);
}
function addLabel(content, x, y, color, size) {
  const label = new Text({ text: content, fontSize: size, color });
  label.moveTo([x, y, 0]);
  dynamicLabels.push(label);
  scene.add(label);
}
function refresh() {
  dynamicLabels.forEach(label => scene.remove(label));
  dynamicLabels = [];
  const sick = 1000 * prevalence / 100;
  const healthy = 1000 - sick;
  const truePositive = sick * 0.9;
  const falsePositive = healthy * 0.1;
  const totalPositive = truePositive + falsePositive;
  const posterior = truePositive / totalPositive;
  addLabel(fmt(sick) + ' sick', -2.9, 1.4, BLUE, 26);
  addLabel('90% test positive', -2.9, 0.93, WHITE, 21);
  addLabel(fmt(truePositive) + ' true positives', -2.9, 0.47, BLUE, 24);
  addLabel(fmt(healthy) + ' healthy', 2.9, 1.4, ORANGE, 26);
  addLabel('10% test positive', 2.9, 0.93, WHITE, 21);
  addLabel(fmt(falsePositive) + ' false positives', 2.9, 0.47, ORANGE, 24);
  addLabel('Zoom in: ' + fmt(totalPositive) + ' positive tests', 0, -0.48, WHITE, 25);
  const boundary = -5.3 + 10.6 * posterior;
  trueSegment.setVertices([[-5.3,-1.55,0],[boundary,-1.55,0],[boundary,-0.95,0],[-5.3,-0.95,0]]);
  falseSegment.setVertices([[boundary,-1.55,0],[5.3,-1.55,0],[5.3,-0.95,0],[boundary,-0.95,0]]);
  addLabel(fmt(truePositive) + ' / ' + fmt(totalPositive) + ' = ' + (100 * posterior).toFixed(1) + '% chance of disease', -0.7, -2.5, YELLOW, 27);
}
refresh();
makeHoverable(sickBox, scene, { hoverScale: 1.02, hoverColor: BLUE });
makeHoverable(healthyBox, scene, { hoverScale: 1.02, hoverColor: ORANGE });

const controls = new Controls(scene, { position: 'bottom-right', width: 230, theme: 'dark' });
controls.addSlider({ label: 'Disease prevalence (%)', min: 0.1, max: 20, value: 1, step: 0.1, onChange: value => { prevalence = value; refresh(); } });
controls.addButton({ label: 'Reset to 1%', onClick: () => { prevalence = 1; refresh(); } });
